// calculate the intersection of a line with a plane
// a = a point on the line
// u = direction of the line
// n = the normal of the plane
// d = the denominator of the equation of the plane
triple lineAndPlaneIntersection(triple a, triple u, triple n, real d) {
  return(a + (n * d)/(u * n));
}

